<template><scroll-view scroll-y class="screen" v-if="a"><view class="tag">{{a.stage}} · {{a.case}}</view><view class="h">{{a.title}}</view><view class="card"><view class="muted">Công thức nguyên bản trong Word</view><view class="formula">{{a.original}}</view><view class="muted">Chuỗi mô phỏng (đã tách ký hiệu)</view><view class="formula">{{a.moves}}</view></view><view class="card"><view class="subtitle">Ghi chú từ tài liệu</view><text>{{a.sourceNote}}</text></view><view class="card"><view class="subtitle">Chú thích bổ sung</view><text>{{a.guide}}</text></view><view class="card"><view class="subtitle">Ký hiệu Rubik</view><text>R: phải · L: trái · U: trên · D: dưới · F: trước · B: sau. Dấu ' là ngược chiều kim đồng hồ khi nhìn trực diện mặt đang xoay; số 2 là xoay 180°.</text></view><button class="btn" @click="play">▶ Mô phỏng 3D công thức</button><button @click="favorite">{{fav?'★ Đã yêu thích':'☆ Thêm yêu thích'}}</button><view class="card"><view class="subtitle">Ghi chú cá nhân (lưu offline)</view><textarea class="notes" v-model="note" placeholder="Nhập mẹo nhớ hoặc lưu ý..."/><button @click="save">Lưu ghi chú</button></view></scroll-view></template>
<script setup>import {ref} from 'vue';import algorithms from '../../static/data/algorithms.json';import {onLoad} from '@dcloudio/uni-app';const a=ref(null),note=ref(''),fav=ref(false);onLoad(({id})=>{a.value=algorithms.find(x=>x.id===id);if(a.value){note.value=uni.getStorageSync('note_'+id)||'';fav.value=!!uni.getStorageSync('fav_'+id)}});const save=()=>{uni.setStorageSync('note_'+a.value.id,note.value);uni.showToast({title:'Đã lưu',icon:'success'})};const favorite=()=>{fav.value=!fav.value;uni.setStorageSync('fav_'+a.value.id,fav.value?'1':'')};const play=()=>uni.navigateTo({url:'/pages/viewer/viewer?id='+a.value.id});</script>
<style scoped>.screen{height:100vh;box-sizing:border-box;padding:30rpx}.subtitle{font-weight:bold;color:#93c5fd;margin-bottom:14rpx}.notes{background:#101827;color:white;min-height:160rpx;width:100%;padding:15rpx;box-sizing:border-box}.muted{font-size:24rpx}</style>
